export const KIND = {"id":47,"example":{"id":"E47","kind":47,"source":"aether","statement":["Write a class `word_chain::Chain` that holds words, where each element holds one word and owns the next element, with these member functions.","`size() const` returns the number of words as an `int`.","`push(const std::string& word)` puts the word first.","`pop()` takes the first word off and returns it.","`peek() const` returns the first word and leaves it on.","`reverse()` turns the order of the words around.","A new chain is empty.","Limits: 0 ≤ words held ≤ 1000; `pop()` and `peek()` are called only when the chain holds a word."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","#include <memory>","#include <string>","#include <utility>","","namespace word_chain {","","class Chain {","    struct Element {","        std::string word {\"\"};","        std::unique_ptr<Element> next {};","    };","    std::unique_ptr<Element> head {};","    int count {0};","public:","    int size() const","    {","        return count;","    }","    void push(const std::string& word)","    {","        head = std::make_unique<Element>(word, std::move(head));","        ++count;","    }","    std::string pop()","    {","        const std::string word {head->word};","        head = std::move(head->next);","        --count;","        return word;","    }","    std::string peek() const","    {","        return head->word;","    }","    void reverse()","    {","        std::unique_ptr<Element> done {};","        while (head) {","            auto rest {std::move(head->next)};","            head->next = std::move(done);","            done = std::move(head);","            head = std::move(rest);","        }","        head = std::move(done);","    }","};","","}  // namespace word_chain"],"frame":[0,2,3,4,6,47,49],"labels":[{"at":2,"level":0,"text":"Include `memory`, the part of the library that holds `std::unique_ptr`."},{"at":8,"level":1,"text":"Write a class that keeps its data in private members."},{"at":9,"level":0,"text":"Make a type that holds several values with `struct`, whose members anyone may reach."},{"at":11,"level":0,"text":"Let each element own the next with `std::unique_ptr<Element>`, which deletes what it owns when it goes."},{"at":16,"level":1,"text":"Write a member function that gives back the data."},{"at":20,"level":1,"text":"Write a member function that puts a new element first."},{"at":22,"level":2,"text":"Make the new element hold the value and the old first one."},{"at":22,"level":0,"text":"Make a new object that a `std::unique_ptr` owns with `std::make_unique`."},{"at":22,"level":0,"text":"Hand over what a `std::unique_ptr` owns with `std::move`, which leaves it empty."},{"at":23,"level":2,"text":"Add one to the size."},{"at":25,"level":1,"text":"Write a member function that takes off the first element and gives back its value."},{"at":27,"level":2,"text":"Keep the value of the first element."},{"at":27,"level":0,"text":"Reach a member of the object a pointer owns with `->`."},{"at":28,"level":2,"text":"Make the next element the first, and take one from the size."},{"at":30,"level":2,"text":"Give back the value."},{"at":32,"level":1,"text":"Write a member function that gives back the value of the first element."},{"at":36,"level":1,"text":"Write a member function that turns the order of the elements around."},{"at":38,"level":2,"text":"Start the turned list empty."},{"at":39,"level":2,"text":"Move each first element to the front of the turned list."},{"at":39,"level":0,"text":"Test whether a pointer owns an object by writing it alone as the test."},{"at":40,"level":0,"text":"Let `auto` give the variable the type of the value it starts with."},{"at":45,"level":2,"text":"Make the turned list the list."}],"blanks":[]}},"trace":{"id":"T47","lines":["#include <forward_list>","#include <iostream>","#include <print>","int main()","{","    std::forward_list<int> chain {};","    int value {0};","    while (std::cin >> value) {","        chain.push_front(value);","    }","    while (!chain.empty()) {","        std::println(\"{}\", chain.front());","        chain.pop_front();","    }","}"],"columns":["chain","value"],"inputs":["4 7\n","1 2 3\n"],"rows":[{"line":6,"values":["[]",""]},{"line":7,"values":["[]","0"]},{"line":8,"values":["[]","4"]},{"line":9,"values":["[4]","4"]},{"line":8,"values":["[4]","7"]},{"line":9,"values":["[7, 4]","7"]},{"line":8,"values":["[7, 4]","7"]},{"line":11,"values":["[7, 4]","7"]},{"line":12,"values":["[7, 4]","7"]},{"line":13,"values":["[4]","7"]},{"line":11,"values":["[4]","7"]},{"line":12,"values":["[4]","7"]},{"line":13,"values":["[]","7"]},{"line":11,"values":["[]","7"]}],"output":"3\n2\n1\n"},"traces":[],"problems":{"47.01":{"id":"47.01","kind":47,"source":"exercism","statement":["Write a class `simple_linked_list::List` that holds `int` values, where each element holds one value and owns the next element, with these member functions.","`size() const` returns the number of values as a `std::size_t`.","`push(int data)` puts the value first.","`pop()` takes the first value off and returns it.","`peek() const` returns the first value and leaves it on.","`reverse()` turns the order of the values around.","`pop()` and `peek()` throw `std::out_of_range` on an empty list.","A new list is empty.","Limits: 0 ≤ values held ≤ 1000; -1000 ≤ each value ≤ 1000."],"examples":[{"input":"EmptyListHasSizeZero","output":""}],"tests":[{"input":"SingletonListHasSizeOne","output":""},{"input":"NonEmptyListHasCorrectSize","output":""},{"input":"ListHasCorrectSizeAfterPop","output":""},{"input":"ListHasCorrectSizeAfterPopAndPush","output":""},{"input":"PopFromSize1","output":""},{"input":"PopFromSizeTwo","output":""},{"input":"PopAndPushList","output":""},{"input":"ReverseEmptyList","output":""},{"input":"ReverseNonEmptyList","output":""},{"input":"Empty list has length of zero","output":""},{"input":"Singleton list has length of one","output":""},{"input":"Non-empty list has correct length","output":""},{"input":"Pop from empty list is an error","output":""},{"input":"Can pop from singleton list","output":""},{"input":"Can pop from non-empty list","output":""},{"input":"Can pop multiple items","output":""},{"input":"Pop updates the count","output":""},{"input":"Can push to an empty list","output":""},{"input":"Can push to an empty list (initial values given)","output":""},{"input":"Can push to a non-empty list","output":""},{"input":"Push updates count","output":""},{"input":"Push and pop","output":""},{"input":"Peek on empty list is an error","output":""},{"input":"Can peek on singleton list","output":""},{"input":"Can peek on non-empty list","output":""},{"input":"Peek does not change the count","output":""},{"input":"Can peek after a pop and push","output":""},{"input":"Reversed non-empty list is reversed","output":""},{"input":"Reversed non-empty list is reversed (count after reverse)","output":""},{"input":"Double reverse","output":""}],"solution":{"lines":["#pragma once","","#include <cstddef>","#include <memory>","#include <stdexcept>","#include <utility>","","namespace simple_linked_list {","","class List {","    struct Element {","        int data {0};","        std::unique_ptr<Element> next {};","    };","    std::unique_ptr<Element> head {};","    std::size_t count {0};","public:","    std::size_t size() const","    {","        return count;","    }","    void push(int data)","    {","        head = std::make_unique<Element>(data, std::move(head));","        ++count;","    }","    int pop()","    {","        const int value {peek()};","        head = std::move(head->next);","        --count;","        return value;","    }","    int peek() const","    {","        if (!head) {","            throw std::out_of_range {\"list is empty\"};","        }","        return head->data;","    }","    void reverse()","    {","        std::unique_ptr<Element> done {};","        while (head) {","            auto rest {std::move(head->next)};","            head->next = std::move(done);","            done = std::move(head);","            head = std::move(rest);","        }","        head = std::move(done);","    }","};","","}  // namespace simple_linked_list"],"frame":[0,2,3,4,5,7,51,53],"labels":[{"at":9,"level":1,"text":"Write a class that keeps its data in private members."},{"at":17,"level":1,"text":"Write a member function that gives back the data."},{"at":21,"level":1,"text":"Write a member function that puts a new element first."},{"at":23,"level":2,"text":"Make the new element hold the value and the old first one."},{"at":24,"level":2,"text":"Add one to the size."},{"at":26,"level":1,"text":"Write a member function that takes off the first element and gives back its value."},{"at":28,"level":2,"text":"Keep the value of the first element."},{"at":29,"level":2,"text":"Make the next element the first, and take one from the size."},{"at":31,"level":2,"text":"Give back the value."},{"at":33,"level":1,"text":"Write a member function that gives back the value of the first element."},{"at":35,"level":2,"text":"Throw `std::out_of_range` when the list is empty."},{"at":38,"level":2,"text":"Give back the value of the first element."},{"at":40,"level":1,"text":"Write a member function that turns the order of the elements around."},{"at":42,"level":2,"text":"Start the turned list empty."},{"at":43,"level":2,"text":"Move each first element to the front of the turned list."},{"at":49,"level":2,"text":"Make the turned list the list."}],"blanks":[{"line":12,"from":8,"to":32},{"line":19,"from":15,"to":20},{"line":21,"from":14,"to":22},{"line":23,"from":15,"to":63},{"line":24,"from":10,"to":15},{"line":26,"from":4,"to":7},{"line":28,"from":25,"to":31},{"line":29,"from":15,"to":36},{"line":31,"from":15,"to":20},{"line":33,"from":4,"to":7},{"line":35,"from":12,"to":17},{"line":38,"from":15,"to":25},{"line":40,"from":4,"to":8},{"line":42,"from":38,"to":40},{"line":43,"from":15,"to":19},{"line":49,"from":15,"to":30}]},"fn":{"slug":"simple-linked-list","commit":"8d139cb0","header":"simple_linked_list.h","name":"simple_linked_list_test.cpp","test":"// Include the header file with the definitions of the functions you create.\r\n#include \"simple_linked_list.h\"\r\n\r\n// Include the test framework.\r\n#ifdef EXERCISM_TEST_SUITE\r\n#include <catch2/catch.hpp>\r\n#else\r\n#include \"test/catch.hpp\"\r\n#endif\r\n\r\n// Declares a single test.\r\nTEST_CASE(\"EmptyListHasSizeZero\") {\r\n    simple_linked_list::List empty{};\r\n    REQUIRE(empty.size() == 0);\r\n}\r\n\r\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"SingletonListHasSizeOne\") {\r\n    simple_linked_list::List list{};\r\n    list.push(44);\r\n    REQUIRE(list.size() == 1);\r\n}\r\n\r\nTEST_CASE(\"NonEmptyListHasCorrectSize\") {\r\n    simple_linked_list::List list{};\r\n    list.push(44);\r\n    list.push(42);\r\n    list.push(47);\r\n    list.push(-11);\r\n    REQUIRE(list.size() == 4);\r\n}\r\n\r\nTEST_CASE(\"ListHasCorrectSizeAfterPop\") {\r\n    simple_linked_list::List list{};\r\n    list.push(24);\r\n    list.push(2);\r\n    list.push(17);\r\n    list.pop();\r\n    REQUIRE(list.size() == 2);\r\n}\r\n\r\nTEST_CASE(\"ListHasCorrectSizeAfterPopAndPush\") {\r\n    simple_linked_list::List list{};\r\n    list.push(242);\r\n    list.push(21);\r\n    list.push(-17);\r\n    list.pop();\r\n    list.push(34);\r\n    REQUIRE(list.size() == 3);\r\n}\r\n\r\nTEST_CASE(\"PopFromSize1\") {\r\n    simple_linked_list::List list{};\r\n    auto desired = 142;\r\n    list.push(desired);\r\n    auto actual = list.pop();\r\n    REQUIRE(actual == desired);\r\n}\r\n\r\nTEST_CASE(\"PopFromSizeTwo\") {\r\n    simple_linked_list::List list{};\r\n    auto desired_top = 112;\r\n    auto desired_bottom = 221;\r\n    list.push(desired_bottom);\r\n    list.push(desired_top);\r\n    auto actual_top = list.pop();\r\n    REQUIRE(actual_top == desired_top);\r\n    auto actual_bottom = list.pop();\r\n    REQUIRE(actual_bottom == desired_bottom);\r\n}\r\n\r\nTEST_CASE(\"PopAndPushList\") {\r\n    simple_linked_list::List list{};\r\n\r\n    list.push(1);\r\n    list.push(2);\r\n    list.push(3);\r\n    auto third = list.pop();\r\n    list.push(4);\r\n    list.push(5);\r\n    auto fifth = list.pop();\r\n    auto forth = list.pop();\r\n    auto second = list.pop();\r\n    list.push(6);\r\n    auto sixth = list.pop();\r\n    auto first = list.pop();\r\n    REQUIRE(first == 1);\r\n    REQUIRE(second == 2);\r\n    REQUIRE(third == 3);\r\n    REQUIRE(forth == 4);\r\n    REQUIRE(fifth == 5);\r\n    REQUIRE(sixth == 6);\r\n}\r\n\r\nTEST_CASE(\"ReverseEmptyList\") {\r\n    simple_linked_list::List empty{};\r\n    empty.reverse();\r\n    REQUIRE(empty.size() == 0);\r\n}\r\n\r\nTEST_CASE(\"ReverseNonEmptyList\") {\r\n    simple_linked_list::List list{};\r\n    for (int i = 0; i < 5; i++) {\r\n        list.push(i);\r\n    }\r\n\r\n    list.reverse();\r\n\r\n    for (int i = 0; i < 5; i++) {\r\n        REQUIRE(list.pop() == i);\r\n    }\r\n}\r\n\r\nTEST_CASE(\"Empty list has length of zero\",\n          \"[962d998c-c203-41e2-8fbd-85a7b98b79b9]\") {\n    simple_linked_list::List list{};\n    REQUIRE(list.size() == 0);\n}\n\nTEST_CASE(\"Singleton list has length of one\",\n          \"[9760262e-d7e4-4639-9840-87e2e2fbb115]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    REQUIRE(list.size() == 1);\n}\n\nTEST_CASE(\"Non-empty list has correct length\",\n          \"[d9955c90-637c-441b-b41d-8cfb48e924a8]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    list.push(2);\n    list.push(3);\n    REQUIRE(list.size() == 3);\n}\n\nTEST_CASE(\"Pop from empty list is an error\",\n          \"[0c3966db-58f9-4632-b94c-8ea13e54c2c8]\") {\n    simple_linked_list::List list{};\n    REQUIRE_THROWS_AS(list.pop(), std::out_of_range);\n}\n\nTEST_CASE(\"Can pop from singleton list\",\n          \"[a4f9d2e1-7425-49ef-9ee8-6c0cb3407cf0]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    REQUIRE(list.pop() == 1);\n}\n\nTEST_CASE(\"Can pop from non-empty list\",\n          \"[6dcbb2c9-d98a-47bc-a010-9c19703d3ea2]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    list.push(2);\n    REQUIRE(list.pop() == 2);\n}\n\nTEST_CASE(\"Can pop multiple items\", \"[e83aade9-f030-4096-aaf0-f9dc6491e6cf]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    list.push(2);\n    REQUIRE(list.pop() == 2);\n    REQUIRE(list.pop() == 1);\n}\n\nTEST_CASE(\"Pop updates the count\", \"[5c46bcf2-c0a9-4654-ae17-f3192436fcf1]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    list.push(2);\n    REQUIRE(list.size() == 2);\n    REQUIRE(list.pop() == 2);\n    REQUIRE(list.size() == 1);\n    REQUIRE(list.pop() == 1);\n    REQUIRE(list.size() == 0);\n}\n\nTEST_CASE(\"Can push to an empty list\",\n          \"[70d747a1-2e84-4ebc-bc3f-dcbee6a05f6b]\") {\n    simple_linked_list::List list{};\n    REQUIRE_NOTHROW(list.push(1));\n}\n\nTEST_CASE(\"Can push to an empty list (initial values given)\",\n          \"[f3197f0a-1fea-45a5-939f-4a5ea60387ec]\") {\n    simple_linked_list::List list{};\n    REQUIRE_NOTHROW(list.push(1));\n}\n\nTEST_CASE(\"Can push to a non-empty list\",\n          \"[391e332e-1f91-4033-b1e0-0e0c17812fa7]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    list.push(2);\n    REQUIRE_NOTHROW(list.push(3));\n}\n\nTEST_CASE(\"Push updates count\", \"[ed4b0e01-3bbd-4895-af25-152b5914b3da]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    list.push(2);\n    list.push(3);\n    REQUIRE(list.size() == 3);\n}\n\nTEST_CASE(\"Push and pop\", \"[41666790-b932-4e5a-b323-e848a83d12d5]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    list.push(2);\n    REQUIRE(list.pop() == 2);\n    list.push(3);\n    REQUIRE(list.size() == 2);\n    REQUIRE(list.pop() == 3);\n    REQUIRE(list.pop() == 1);\n    REQUIRE(list.size() == 0);\n}\n\nTEST_CASE(\"Peek on empty list is an error\",\n          \"[930a4a5c-76f6-47ec-9be3-4e70993173a1]\") {\n    simple_linked_list::List list{};\n    REQUIRE_THROWS_AS(list.peek(), std::out_of_range);\n}\n\nTEST_CASE(\"Can peek on singleton list\",\n          \"[43255a50-d919-4e81-afce-e4a271eaedbd]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    REQUIRE(list.peek() == 1);\n}\n\nTEST_CASE(\"Can peek on non-empty list\",\n          \"[48353020-e25d-4621-a854-e35fb1e15fa7]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    list.push(2);\n    REQUIRE(list.peek() == 2);\n}\n\nTEST_CASE(\"Peek does not change the count\",\n          \"[96fcead9-a713-46c2-8005-3f246c873851]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    list.push(2);\n    REQUIRE(list.peek() == 2);\n    REQUIRE(list.size() == 2);\n}\n\nTEST_CASE(\"Can peek after a pop and push\",\n          \"[7576ed05-7ff7-4b84-8efb-d34d62c110f5]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    list.push(2);\n    REQUIRE(list.peek() == 2);\n    REQUIRE(list.pop() == 2);\n    REQUIRE(list.peek() == 1);\n    list.push(3);\n    REQUIRE(list.peek() == 3);\n}\n\nTEST_CASE(\"Reversed non-empty list is reversed\",\n          \"[92851ebe-9f52-4406-b92e-0718c441a2ab]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    list.push(2);\n    list.push(3);\n    list.reverse();\n    REQUIRE(list.pop() == 1);\n    REQUIRE(list.pop() == 2);\n    REQUIRE(list.pop() == 3);\n}\n\nTEST_CASE(\"Reversed non-empty list is reversed (count after reverse)\",\n          \"[1210eeda-b23f-4790-930c-7ac6d0c8e723]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    list.push(2);\n    list.push(3);\n    list.reverse();\n    REQUIRE(list.size() == 3);\n    REQUIRE(list.pop() == 1);\n    REQUIRE(list.pop() == 2);\n    REQUIRE(list.pop() == 3);\n}\n\nTEST_CASE(\"Double reverse\", \"[9b53af96-7494-4cfa-9b77-b7366fed5c4c]\") {\n    simple_linked_list::List list{};\n    list.push(1);\n    list.push(2);\n    list.push(3);\n    list.reverse();\n    list.reverse();\n    REQUIRE(list.pop() == 3);\n    REQUIRE(list.pop() == 2);\n    REQUIRE(list.pop() == 1);\n}\n#endif\n","setup":["simple_linked_list::List empty{};"],"calls":[{"call":"empty.size()","expected":"0"}]}},"47.02":{"id":"47.02","kind":47,"source":"aether","statement":["Write a class `plates::Stack` that holds plate weights as `int` values, where each element holds one weight and owns the next element, with these member functions.","`total() const` returns the sum of the weights held, as an `int`.","`put(int weight)` puts the weight on top.","`take()` takes the top weight off and returns it.","`top() const` returns the top weight and leaves it on.","`flip()` turns the order of the weights around, so the bottom weight is on top.","`take()` and `top()` throw `std::out_of_range` when the stack is empty.","A new stack is empty, with total 0.","Limits: 0 ≤ weights held ≤ 1000; 1 ≤ each weight ≤ 1000."],"examples":[{"input":"put_two_and_take_the_top","output":""}],"tests":[{"input":"new_stack_is_empty","output":""},{"input":"take_from_empty_throws","output":""},{"input":"top_of_empty_throws","output":""},{"input":"top_leaves_the_weight_on","output":""},{"input":"take_until_empty","output":""},{"input":"flip_puts_the_bottom_on_top","output":""},{"input":"flip_empty_and_one","output":""},{"input":"many_weights","output":""}],"solution":{"lines":["#pragma once","","#include <memory>","#include <stdexcept>","#include <utility>","","namespace plates {","","class Stack {","    struct Element {","        int weight {0};","        std::unique_ptr<Element> next {};","    };","    std::unique_ptr<Element> head {};","    int sum {0};","public:","    int total() const","    {","        return sum;","    }","    void put(int weight)","    {","        head = std::make_unique<Element>(weight,","            std::move(head));","        sum += weight;","    }","    int take()","    {","        const int weight {top()};","        head = std::move(head->next);","        sum -= weight;","        return weight;","    }","    int top() const","    {","        if (!head) {","            throw std::out_of_range {\"the stack is empty\"};","        }","        return head->weight;","    }","    void flip()","    {","        std::unique_ptr<Element> done {};","        while (head) {","            auto rest {std::move(head->next)};","            head->next = std::move(done);","            done = std::move(head);","            head = std::move(rest);","        }","        head = std::move(done);","    }","};","","}  // namespace plates"],"frame":[0,2,3,4,6,51,53],"labels":[{"at":8,"level":1,"text":"Write a class that keeps its data in private members."},{"at":16,"level":1,"text":"Write a member function that gives back the data."},{"at":20,"level":1,"text":"Write a member function that puts a new element first."},{"at":22,"level":2,"text":"Make the new element hold the value and the old first one."},{"at":24,"level":2,"text":"Add the weight to the total."},{"at":26,"level":1,"text":"Write a member function that takes off the first element and gives back its value."},{"at":28,"level":2,"text":"Keep the value of the first element."},{"at":29,"level":2,"text":"Make the next element the first, and take its weight from the total."},{"at":31,"level":2,"text":"Give back the value."},{"at":33,"level":1,"text":"Write a member function that gives back the value of the first element."},{"at":35,"level":2,"text":"Throw `std::out_of_range` when the list is empty."},{"at":38,"level":2,"text":"Give back the value of the first element."},{"at":40,"level":1,"text":"Write a member function that turns the order of the elements around."},{"at":42,"level":2,"text":"Start the turned list empty."},{"at":43,"level":2,"text":"Move each first element to the front of the turned list."},{"at":49,"level":2,"text":"Make the turned list the list."}],"blanks":[{"line":11,"from":8,"to":32},{"line":18,"from":15,"to":18},{"line":20,"from":13,"to":23},{"line":22,"from":15,"to":40},{"line":24,"from":15,"to":21},{"line":26,"from":4,"to":7},{"line":28,"from":26,"to":31},{"line":29,"from":15,"to":36},{"line":31,"from":15,"to":21},{"line":33,"from":4,"to":7},{"line":35,"from":12,"to":17},{"line":38,"from":15,"to":27},{"line":40,"from":4,"to":8},{"line":42,"from":38,"to":40},{"line":43,"from":15,"to":19},{"line":49,"from":15,"to":30}]},"fn":{"slug":"plates","commit":"","header":"plates.h","name":"plates_test.cpp","test":"#include \"plates.h\"\n#include \"test/catch.hpp\"\n\nTEST_CASE(\"put_two_and_take_the_top\") {\n    plates::Stack stack {};\n    stack.put(3);\n    stack.put(5);\n    REQUIRE(stack.total() == 8);\n    REQUIRE(stack.take() == 5);\n    REQUIRE(stack.total() == 3);\n}\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"new_stack_is_empty\") {\n    const plates::Stack stack {};\n    REQUIRE(stack.total() == 0);\n}\nTEST_CASE(\"take_from_empty_throws\") {\n    plates::Stack stack {};\n    REQUIRE_THROWS_AS(stack.take(), std::out_of_range);\n}\nTEST_CASE(\"top_of_empty_throws\") {\n    const plates::Stack stack {};\n    REQUIRE_THROWS_AS(stack.top(), std::out_of_range);\n}\nTEST_CASE(\"top_leaves_the_weight_on\") {\n    plates::Stack stack {};\n    stack.put(7);\n    REQUIRE(stack.top() == 7);\n    REQUIRE(stack.top() == 7);\n    REQUIRE(stack.total() == 7);\n}\nTEST_CASE(\"take_until_empty\") {\n    plates::Stack stack {};\n    stack.put(1);\n    stack.put(2);\n    REQUIRE(stack.take() == 2);\n    REQUIRE(stack.take() == 1);\n    REQUIRE(stack.total() == 0);\n    REQUIRE_THROWS_AS(stack.take(), std::out_of_range);\n}\nTEST_CASE(\"flip_puts_the_bottom_on_top\") {\n    plates::Stack stack {};\n    stack.put(1);\n    stack.put(2);\n    stack.put(3);\n    stack.flip();\n    REQUIRE(stack.take() == 1);\n    REQUIRE(stack.take() == 2);\n    REQUIRE(stack.take() == 3);\n}\nTEST_CASE(\"flip_empty_and_one\") {\n    plates::Stack stack {};\n    stack.flip();\n    REQUIRE(stack.total() == 0);\n    stack.put(4);\n    stack.flip();\n    REQUIRE(stack.top() == 4);\n}\nTEST_CASE(\"many_weights\") {\n    plates::Stack stack {};\n    for (int weight {1}; weight <= 1000; ++weight) {\n        stack.put(weight);\n    }\n    REQUIRE(stack.total() == 500500);\n    stack.flip();\n    REQUIRE(stack.top() == 1);\n    REQUIRE(stack.take() == 1);\n    REQUIRE(stack.total() == 500499);\n}\n#endif\n","setup":["plates::Stack stack {};","stack.put(3);","stack.put(5);"],"calls":[{"call":"stack.total()","expected":"8"},{"call":"stack.take()","expected":"5"},{"call":"stack.total()","expected":"3"}]}}}}
